"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-0299-01-01:0":{"b": ["Ufalme wa Kush — kipindi cha Meroe: kinaanza", "ee436c47"], "d": ["Kipindi cha Meroe kinachoanza kwa kuhamia kwa kitovu cha Kush kutoka Napata hadi Meroe (karibu 300 KK) na kinachoenea hadi BK 350.", "5c13abcf"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1069-01-01:0":{"b": ["Ufalme wa Kush — kipindi cha Napata: kinaanza", "fd21e916"], "d": ["Kipindi cha nasaba ya Kush chenye kitovu Napata; kitovu kinahamia Meroe ~300 KK. Nasaba ya XXV (Kush) iliyoiteka Misri inatokea katika kipindi hiki — tarehe za Nasaba ya XXV HAZIPO katika chanzo hiki.", "b8938f36"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1449-01-01:0":{"b": ["Ufalme/utamaduni wa Kerma (Kush): wamalizika", "95c2812c"], "d": ["Ufalme wa Nubia wenye kitovu Kerma chini ya Maporomoko ya Tatu; ukipita awamu za Kerma ya Kale (~2500), ya Kati, ya Kawaida, unaisha ~1450 KK. Honegger 2005: 'Kerma Classique (vers 1500 av. J.-C.)' makazi yaliyozingirwa.", "5ea1ab25"]},
