"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1556-01-01:0":{"b": ["Ufalme Mpya (mwanzo wa Nasaba ya XVIII: I. Ahmose): unaanza", "0472735f"], "d": ["Kupanda kiti cha enzi kwa I. Ahmose (mwanzo wa Nasaba ya XVIII/Ufalme Mpya) katika mfano wa Bronk Ramsey na wengine 1570–1544 KK (2σ).", "13b3514b"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-1811-01-01:0":{"b": ["Ufalme wa Kati: wamalizika", "51fa178c"], "d": ["Kipindi cha pili kikubwa cha umoja cha Misri; makala inaunga mkono kronolojia ya 'High' (Low inakataliwa), kipindi cha Senusret III kimepimwa kwa pete za mihimili ya ngome ya Uronarti (Sudan).", "e792785c"]},
